/// ⚖️ `brep:out` exchanges every shape the modelspace shows, each in its class: the forest's Shape and Building solids,
/// the Energy pane's baseplate face and the Structure pane's wall/column wires and face. G12's MCP coverage battery (hub
/// p33-3/p33-4) measured `brep export failed` here — the kernel refused every face and wire as "not a solid".
#[semio_framework_async_macros::async_test]
async fn modelspace_brep_out_exchanges_every_pane_shape() {
    use semio_s_artifact_stdio_semio::standards::v1::subsets::brep::schema::engine::{BrepKernel, GeometryKind};
    let view = forest_view();
    let mut kernel = cad_brep_kernel();
    let kinds: Vec<GeometryKind> = collect_modelspace_solids(&mut kernel, &view).iter().map(|shape| kernel.kind(shape).expect("kind")).collect();
    let count = |kind: GeometryKind| kinds.iter().filter(|shape| **shape == kind).count();
    let (solids, faces, wires) = (count(GeometryKind::Solid), count(GeometryKind::Face), count(GeometryKind::Wire));
    assert!(solids > 0 && faces > 0 && wires > 0, "the forest modelspace shows solids, faces and wires: {kinds:?}");
    assert_eq!(solids + faces + wires, kinds.len(), "the panes show only solids, faces and wires: {kinds:?}");
    let history = empty_history();
    let media = <CadPlayApp as ArtifactEditor>::export_media("brep:out", &ArtifactView::new(&view.document, &history)).expect("brep:out exports the forest modelspace");
    let MediaPayload::Structured { json, .. } = media.payload else { panic!("brep:out is a structured payload") };
    let text = String::from_utf8(base64_codec::base64_standard_decode(&json).expect("base64")).expect("utf-8");
    let document = semio_s_artifact_stdio_contract::part21::parse_part21(&text).expect("the exchange parses as ISO 10303-21");
    let census = |name: &str| document.instances.iter().filter(|instance| instance.is_type(name)).count();
    assert_eq!(census("MANIFOLD_SOLID_BREP") + census("BREP_WITH_VOIDS"), solids, "every solid is a solid brep");
    assert_eq!(census("SHELL_BASED_SURFACE_MODEL"), 1, "one surface model");
    assert_eq!(census("OPEN_SHELL"), faces, "every free face is its own open shell");
    assert_eq!(census("EDGE_BASED_WIREFRAME_MODEL"), 1, "one wireframe model");
    assert!(census("CONNECTED_EDGE_SET") >= 1 && census("CONNECTED_EDGE_SET") <= wires, "the wires' edges are exchanged as connected edge sets");
    assert_eq!(census("SHAPE_DEFINITION_REPRESENTATION"), 3, "one representation per content class");
}
