/// 📤️ Encodes `shapes` (the pane's solids, faces and wires) for `format` through stdio's real codecs: OBJ/STL tessellate
/// them via the live kernel into a `semio/mesh` snapshot and call stdio's own `SemioMeshToObj`/`SemioMeshToStl` + text/
/// binary grammar encoders (a wire has no surface and is not part of a mesh file); STEP is the kernel's `export_step` —
/// stdio's one AP214 writer, which exchanges solids, free faces and free wires each in their own representation. STL is
/// base64-wrapped since it is a binary format, OBJ/STEP stay UTF-8 text. `Err` names why nothing could be written.
pub fn export_solids_as(kernel: &mut Brep, solids: &[GeometryHandle], format: &str, stem: &str) -> Result<CadSolidExport, String> {
    let extension = cad_solid_export_extension(format).ok_or_else(|| format!("{format} is not a shape export format"))?;
    let filename = format!("{stem}.{extension}");
    let mime_type = cad_solid_export_mime_type(format).ok_or_else(|| format!("{format} is not a shape export format"))?.to_string();
    match format {
        CAD_SOLID_EXPORT_DIALECT_OBJ => {
            let mesh_snapshot = semio_mesh_snapshot_from_solids(kernel, solids, 0.1).ok_or("no shape tessellates to a surface")?;
            let obj_snapshot = semio_framework_plugin::resolve_ready(SemioMeshToObj::serialize(&mesh_snapshot)).map_err(|error| error.to_string())?;
            Ok(CadSolidExport { filename, data: DslValue::String(encode_obj(&obj_snapshot)), mime_type, encoding: None })
        }
        CAD_SOLID_EXPORT_DIALECT_STL => {
            let mesh_snapshot = semio_mesh_snapshot_from_solids(kernel, solids, 0.1).ok_or("no shape tessellates to a surface")?;
            let stl_snapshot = semio_framework_plugin::resolve_ready(SemioMeshToStl::serialize(&mesh_snapshot)).map_err(|error| error.to_string())?;
            let encoded = base64_codec::base64_standard_encode(encode_stl_binary(&stl_snapshot));
            Ok(CadSolidExport { filename, data: DslValue::String(encoded), mime_type, encoding: Some("base64".into()) })
        }
        CAD_SOLID_EXPORT_DIALECT_STEP => Ok(CadSolidExport { filename, data: DslValue::String(kernel.export_step(solids).map_err(|error| error.to_string())?), mime_type, encoding: None }),
        other => Err(format!("{other} is not a shape export format")),
    }
}
