// #region 🔖️Write
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn s(text: &str) -> Part21Value {
    Part21Value::Str(text.to_string())
}
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn xyz(p: SemioPoint3) -> Part21Value {
    Part21Value::List(vec![Part21Value::Real(p.x.into()), Part21Value::Real(p.y.into()), Part21Value::Real(p.z.into())])
}
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn bool_enum(b: bool) -> Part21Value {
    Part21Value::Enum(if b { "T".to_string() } else { "F".to_string() })
}
/// 🔁️ Inverse of the `📥️import` leaf's `expand_knots`: a flat knot vector -> `(multiplicities,
/// distinct_knots)`, grouping consecutive equal (within float-epsilon) values into runs.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn compress_knots(flat: &[f64]) -> (Vec<i64>, Vec<f64>) {
    let mut mults: Vec<i64> = Vec::new();
    let mut uniq: Vec<f64> = Vec::new();
    for &k in flat {
        if let Some(&last) = uniq.last() {
            if (k - last).abs() < 1e-9 {
                *mults.last_mut().expect("uniq and mults grow together") += 1;
                continue;
            }
        }
        uniq.push(k);
        mults.push(1);
    }
    (mults, uniq)
}
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn point_to_part21(b: &mut Part21Builder, p: SemioPoint3) -> u64 {
    b.alloc("CARTESIAN_POINT", vec![s(""), xyz(p)])
}
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn direction_to_part21(b: &mut Part21Builder, d: SemioPoint3) -> u64 {
    b.alloc("DIRECTION", vec![s(""), xyz(d)])
}
/// 📐️ `AXIS2_PLACEMENT_3D` with the ref_direction (in-plane rotation) always ` — see module
/// doc comment.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn axis_placement_to_part21(b: &mut Part21Builder, origin: SemioPoint3, axis: SemioPoint3) -> u64 {
    let origin_id = point_to_part21(b, origin);
    let axis_id = direction_to_part21(b, axis);
    b.alloc("AXIS2_PLACEMENT_3D", vec![s(""), Part21Value::Ref(origin_id), Part21Value::Ref(axis_id), Part21Value::Unset])
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn curve_to_part21(b: &mut Part21Builder, curve: &BrepCurve) -> u64 {
    match curve {
        BrepCurve::Line { origin, direction } => {
            let point_id = point_to_part21(b, *origin);
            let dir_id = direction_to_part21(b, *direction);
            let vector_id = b.alloc("VECTOR", vec![s(""), Part21Value::Ref(dir_id), Part21Value::Real(1.0.into())]);
            b.alloc("LINE", vec![s(""), Part21Value::Ref(point_id), Part21Value::Ref(vector_id)])
        }
        BrepCurve::Circle { center, axis, radius } => {
            let pos_id = axis_placement_to_part21(b, *center, *axis);
            b.alloc("CIRCLE", vec![s(""), Part21Value::Ref(pos_id), Part21Value::Real((*radius).into())])
        }
        BrepCurve::Ellipse { center, axis, radius_major, radius_minor } => {
            let pos_id = axis_placement_to_part21(b, *center, *axis);
            b.alloc("ELLIPSE", vec![s(""), Part21Value::Ref(pos_id), Part21Value::Real((*radius_major).into()), Part21Value::Real((*radius_minor).into())])
        }
        BrepCurve::Nurbs { control_points, weights, degree, knots } => {
            let cp_ids: Vec<Part21Value> = control_points.iter().map(|p| Part21Value::Ref(point_to_part21(b, *p))).collect();
            let (mults, uniq_knots) = compress_knots(knots);
            let base_args = vec![
                s(""),
                Part21Value::Int(*degree as i64),
                Part21Value::List(cp_ids),
                Part21Value::Enum("UNSPECIFIED".into()),
                Part21Value::Enum("F".into()),
                Part21Value::Enum("F".into()),
                Part21Value::List(mults.iter().map(|m| Part21Value::Int(*m)).collect()),
                Part21Value::List(uniq_knots.iter().map(|k| Part21Value::Real((*k).into())).collect()),
                Part21Value::Enum("UNSPECIFIED".into()),
            ];
            let id = b.alloc("B_SPLINE_CURVE_WITH_KNOTS", base_args);
            let uniform = weights.iter().all(|w| (w - 1.0).abs() < 1e-12);
            if !uniform {
                let weight_args = vec![Part21Value::List(weights.iter().map(|w| Part21Value::Real((*w).into())).collect())];
                b.instances.last_mut().expect("just allocated above").entities.push(("RATIONAL_B_SPLINE_CURVE".to_string(), weight_args));
            }
            id
        }
    }
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn surface_to_part21(b: &mut Part21Builder, surface: &BrepSurface) -> u64 {
    match surface {
        BrepSurface::Plane { origin, normal } => {
            let pos_id = axis_placement_to_part21(b, *origin, *normal);
            b.alloc("PLANE", vec![s(""), Part21Value::Ref(pos_id)])
        }
        BrepSurface::Cylinder { origin, axis, radius } => {
            let pos_id = axis_placement_to_part21(b, *origin, *axis);
            b.alloc("CYLINDRICAL_SURFACE", vec![s(""), Part21Value::Ref(pos_id), Part21Value::Real((*radius).into())])
        }
        BrepSurface::Cone { origin, axis, radius, half_angle } => {
            let pos_id = axis_placement_to_part21(b, *origin, *axis);
            b.alloc("CONICAL_SURFACE", vec![s(""), Part21Value::Ref(pos_id), Part21Value::Real((*radius).into()), Part21Value::Real((*half_angle).into())])
        }
        BrepSurface::Sphere { center, radius } => {
            let pos_id = axis_placement_to_part21(b, *center, SemioPoint3 { x: 0.0, y: 0.0, z: 1.0 });
            b.alloc("SPHERICAL_SURFACE", vec![s(""), Part21Value::Ref(pos_id), Part21Value::Real((*radius).into())])
        }
        BrepSurface::Torus { center, axis, major_radius, minor_radius } => {
            let pos_id = axis_placement_to_part21(b, *center, *axis);
            b.alloc("TOROIDAL_SURFACE", vec![s(""), Part21Value::Ref(pos_id), Part21Value::Real((*major_radius).into()), Part21Value::Real((*minor_radius).into())])
        }
        BrepSurface::Nurbs { control_points, weights, u_count, v_count, degree_u, degree_v, knots_u, knots_v } => {
            let (u, v) = (*u_count as usize, *v_count as usize);
            let mut rows = Vec::with_capacity(u);
            for ui in 0..u {
                let mut row = Vec::with_capacity(v);
                for vi in 0..v {
                    row.push(Part21Value::Ref(point_to_part21(b, control_points[ui * v + vi])));
                }
                rows.push(Part21Value::List(row));
            }
            let (u_mults, u_uniq) = compress_knots(knots_u);
            let (v_mults, v_uniq) = compress_knots(knots_v);
            let base_args = vec![
                s(""),
                Part21Value::Int(*degree_u as i64),
                Part21Value::Int(*degree_v as i64),
                Part21Value::List(rows),
                Part21Value::Enum("UNSPECIFIED".into()),
                Part21Value::Enum("F".into()),
                Part21Value::Enum("F".into()),
                Part21Value::Enum("F".into()),
                Part21Value::List(u_mults.iter().map(|m| Part21Value::Int(*m)).collect()),
                Part21Value::List(v_mults.iter().map(|m| Part21Value::Int(*m)).collect()),
                Part21Value::List(u_uniq.iter().map(|k| Part21Value::Real((*k).into())).collect()),
                Part21Value::List(v_uniq.iter().map(|k| Part21Value::Real((*k).into())).collect()),
                Part21Value::Enum("UNSPECIFIED".into()),
            ];
            let id = b.alloc("B_SPLINE_SURFACE_WITH_KNOTS", base_args);
            let uniform = weights.iter().all(|w| (w - 1.0).abs() < 1e-12);
            if !uniform {
                let mut wrows = Vec::with_capacity(u);
                for ui in 0..u {
                    let mut wrow = Vec::with_capacity(v);
                    for vi in 0..v {
                        wrow.push(Part21Value::Real(weights[ui * v + vi].into()));
                    }
                    wrows.push(Part21Value::List(wrow));
                }
                b.instances.last_mut().expect("just allocated above").entities.push(("RATIONAL_B_SPLINE_SURFACE".to_string(), vec![Part21Value::List(wrows)]));
            }
            id
        }
    }
}

/// 📏️ The exchange's distance uncertainty in model units (metres) — the kernel's confusion tolerance.
const EXCHANGE_UNCERTAINTY: f64 = 1e-7;

/// 🧩️ One complex instance `(A(…) B(…) …)` (ISO 10303-21 §11.2.5.3 external mapping); `leaves` come in the
/// alphabetical order the standard requires.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn alloc_complex(b: &mut Part21Builder, leaves: Vec<(&str, Vec<Part21Value>)>) -> u64 {
    let mut leaves = leaves.into_iter();
    let (first, args) = leaves.next().expect("a complex instance has at least one leaf");
    let id = b.alloc(first, args);
    b.instances.last_mut().expect("just allocated above").entities.extend(leaves.map(|(name, args)| (name.to_string(), args)));
    id
}

/// 🌐️ The one `GEOMETRIC_REPRESENTATION_CONTEXT` every representation of the exchange shares: metre, radian and
/// steradian SI units and the [`EXCHANGE_UNCERTAINTY`] distance accuracy.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn geometric_context_to_part21(b: &mut Part21Builder) -> u64 {
    let length = alloc_complex(b, vec![("LENGTH_UNIT", vec![]), ("NAMED_UNIT", vec![Part21Value::Derived]), ("SI_UNIT", vec![Part21Value::Unset, Part21Value::Enum("METRE".into())])]);
    let angle = alloc_complex(b, vec![("NAMED_UNIT", vec![Part21Value::Derived]), ("PLANE_ANGLE_UNIT", vec![]), ("SI_UNIT", vec![Part21Value::Unset, Part21Value::Enum("RADIAN".into())])]);
    let solid_angle = alloc_complex(b, vec![("NAMED_UNIT", vec![Part21Value::Derived]), ("SI_UNIT", vec![Part21Value::Unset, Part21Value::Enum("STERADIAN".into())]), ("SOLID_ANGLE_UNIT", vec![])]);
    let uncertainty = b.alloc(
        "UNCERTAINTY_MEASURE_WITH_UNIT",
        vec![Part21Value::Typed { name: "LENGTH_MEASURE".into(), items: vec![Part21Value::Real(EXCHANGE_UNCERTAINTY.into())] }, Part21Value::Ref(length), s("distance_accuracy_value"), s("confusion accuracy")],
    );
    alloc_complex(
        b,
        vec![
            ("GEOMETRIC_REPRESENTATION_CONTEXT", vec![Part21Value::Int(3)]),
            ("GLOBAL_UNCERTAINTY_ASSIGNED_CONTEXT", vec![Part21Value::List(vec![Part21Value::Ref(uncertainty)])]),
            ("GLOBAL_UNIT_ASSIGNED_CONTEXT", vec![Part21Value::List(vec![Part21Value::Ref(length), Part21Value::Ref(angle), Part21Value::Ref(solid_angle)])]),
            ("REPRESENTATION_CONTEXT", vec![s(""), s("")]),
        ],
    )
}

/// 📦️ The AP214 product structure (`PRODUCT` → `PRODUCT_DEFINITION` → `PRODUCT_DEFINITION_SHAPE`) the exchange's shape
/// representations hang off — without it a conformant reader finds no shape root to transfer.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn product_shape_to_part21(b: &mut Part21Builder) -> u64 {
    let application = b.alloc("APPLICATION_CONTEXT", vec![s("automotive design")]);
    b.alloc("APPLICATION_PROTOCOL_DEFINITION", vec![s("international standard"), s("automotive_design"), Part21Value::Int(2000), Part21Value::Ref(application)]);
    let product_context = b.alloc("PRODUCT_CONTEXT", vec![s(""), Part21Value::Ref(application), s("mechanical")]);
    let product = b.alloc("PRODUCT", vec![s("semio"), s("semio"), s(""), Part21Value::List(vec![Part21Value::Ref(product_context)])]);
    let formation = b.alloc("PRODUCT_DEFINITION_FORMATION", vec![s(""), s(""), Part21Value::Ref(product)]);
    let definition_context = b.alloc("PRODUCT_DEFINITION_CONTEXT", vec![s("part definition"), Part21Value::Ref(application), s("design")]);
    let definition = b.alloc("PRODUCT_DEFINITION", vec![s("design"), s(""), Part21Value::Ref(formation), Part21Value::Ref(definition_context)]);
    b.alloc("PRODUCT_DEFINITION_SHAPE", vec![s(""), s(""), Part21Value::Ref(definition)])
}

/// 🗂️ One typed shape representation of `items`, bound to the product shape by its own
/// `SHAPE_DEFINITION_REPRESENTATION`; an empty content class writes nothing.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn representation_to_part21(b: &mut Part21Builder, kind: &str, items: Vec<Part21Value>, context: u64, product_shape: u64) {
    if items.is_empty() {
        return;
    }
    let representation = b.alloc(kind, vec![s(""), Part21Value::List(items), Part21Value::Ref(context)]);
    b.alloc("SHAPE_DEFINITION_REPRESENTATION", vec![Part21Value::Ref(product_shape), Part21Value::Ref(representation)]);
}

/// 🌳️ Union-find root of edge index `i` (path halving).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn component_root(parent: &mut [usize], mut i: usize) -> usize {
    while parent[i] != i {
        parent[i] = parent[parent[i]];
        i = parent[i];
    }
    i
}

/// 🕸️ The indices of the snapshot's free edges (no loop uses them: wires, loose edges) grouped into the components their
/// shared vertices connect — components ordered by their first edge, members in snapshot order.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn free_edge_components(snapshot: &SemioBrepSnapshot) -> Vec<Vec<usize>> {
    let looped: HashSet<&str> = snapshot.loops.iter().flat_map(|l| l.edges.iter().map(|le| le.edge.as_str())).collect();
    let free: Vec<usize> = (0..snapshot.edges.len()).filter(|&i| !looped.contains(snapshot.edges[i].id.as_str())).collect();
    let mut parent: Vec<usize> = (0..snapshot.edges.len()).collect();
    let mut first_at_vertex: HashMap<&str, usize> = HashMap::new();
    for &i in &free {
        for vertex in [snapshot.edges[i].start_vertex.as_str(), snapshot.edges[i].end_vertex.as_str()] {
            match first_at_vertex.get(vertex).copied() {
                Some(j) => {
                    let (a, b) = (component_root(&mut parent, i), component_root(&mut parent, j));
                    parent[a.max(b)] = a.min(b);
                }
                None => {
                    first_at_vertex.insert(vertex, i);
                }
            }
        }
    }
    let mut position: HashMap<usize, usize> = HashMap::new();
    let mut components: Vec<Vec<usize>> = Vec::new();
    for &i in &free {
        let root = component_root(&mut parent, i);
        match position.get(&root).copied() {
            Some(at) => components[at].push(i),
            None => {
                position.insert(root, components.len());
                components.push(vec![i]);
            }
        }
    }
    components
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
/// 📤️ `snapshot` as a complete AP214 exchange graph — the semio brep's ONE STEP writer (the kernel's `Brep::export_step`
/// projects its shapes to a snapshot and writes it here; stdio's `SemioBrepToStep` serializer wraps it). A conformant reader
/// transfers it (OpenCascade's `STEPControl_Reader` is the oracle of the `📤️step-exchange` fixture):
/// - the product structure (`PRODUCT` … `PRODUCT_DEFINITION_SHAPE`) every shape representation hangs off;
/// - one `GEOMETRIC_REPRESENTATION_CONTEXT` in SI units — semio geometry is metric, one model unit is one metre
///   (`SI_UNIT($,.METRE.)`), angles are radians, distance uncertainty 1e-7 m;
/// - one typed representation per content class, each bound to the product by its own `SHAPE_DEFINITION_REPRESENTATION`:
///   `ADVANCED_BREP_SHAPE_REPRESENTATION` for the solids (`MANIFOLD_SOLID_BREP`; `BREP_WITH_VOIDS`, whose voids are
///   `ORIENTED_CLOSED_SHELL(.F.)` as ISO 10303-42 requires, their faces `ORIENTED_FACE(.F.)` so the orientation a reader sees is
///   the snapshot's own), `MANIFOLD_SURFACE_SHAPE_REPRESENTATION` for the shells no solid owns and the faces no shell owns
///   (`SHELL_BASED_SURFACE_MODEL` of `OPEN_SHELL`s — a free face is its own one-face open shell),
///   `EDGE_BASED_WIREFRAME_SHAPE_REPRESENTATION` for the edges no loop uses (`EDGE_BASED_WIREFRAME_MODEL`, one
///   `CONNECTED_EDGE_SET` per vertex-connected component).
///
/// Entity allocation and Part-21 text stay the stdio contract's own (`Part21Builder`/`write_part21`). Honest boundaries: a shell
/// face whose `BrepShellFace.orientation` disagrees with the face is an `ORIENTED_FACE(.F.)` member;
/// `AXIS2_PLACEMENT_3D.ref_direction` is always `$` (`BrepCurve`/`BrepSurface` carry no in-plane rotation); a vertex no edge
/// uses has no representation; semio ids are not STEP ids — every export mints fresh, sequential instance ids.
pub fn semio_brep_part21(snapshot: &SemioBrepSnapshot) -> Result<Part21Document, String> {
    let mut b = Part21Builder::new();
    let product_shape = product_shape_to_part21(&mut b);
    let context = geometric_context_to_part21(&mut b);

    let mut vertex_ids: HashMap<&str, u64> = HashMap::new();
    for v in &snapshot.vertices {
        let point_id = point_to_part21(&mut b, v.point);
        let vertex_id = b.alloc("VERTEX_POINT", vec![s(""), Part21Value::Ref(point_id)]);
        vertex_ids.insert(v.id.as_str(), vertex_id);
    }

    let mut edge_ids: HashMap<&str, u64> = HashMap::new();
    for e in &snapshot.edges {
        let &start = vertex_ids.get(e.start_vertex.as_str()).ok_or_else(|| format!("edge {:?}: dangling start_vertex {:?}", e.id, e.start_vertex))?;
        let &end = vertex_ids.get(e.end_vertex.as_str()).ok_or_else(|| format!("edge {:?}: dangling end_vertex {:?}", e.id, e.end_vertex))?;
        let curve_id = curve_to_part21(&mut b, &e.curve);
        let edge_id = b.alloc("EDGE_CURVE", vec![s(""), Part21Value::Ref(start), Part21Value::Ref(end), Part21Value::Ref(curve_id), bool_enum(true)]);
        edge_ids.insert(e.id.as_str(), edge_id);
    }

    let mut loop_ids: HashMap<&str, u64> = HashMap::new();
    for l in &snapshot.loops {
        let mut members = Vec::with_capacity(l.edges.len());
        for le in &l.edges {
            let &edge_ref = edge_ids.get(le.edge.as_str()).ok_or_else(|| format!("loop {:?}: dangling edge {:?}", l.id, le.edge))?;
            let oe_id = b.alloc("ORIENTED_EDGE", vec![s(""), Part21Value::Derived, Part21Value::Derived, Part21Value::Ref(edge_ref), bool_enum(le.orientation)]);
            members.push(Part21Value::Ref(oe_id));
        }
        let loop_id = b.alloc("EDGE_LOOP", vec![s(""), Part21Value::List(members)]);
        loop_ids.insert(l.id.as_str(), loop_id);
    }

    let mut face_ids: HashMap<&str, u64> = HashMap::new();
    for f in &snapshot.faces {
        let &outer_ref = loop_ids.get(f.outer_loop.as_str()).ok_or_else(|| format!("face {:?}: dangling outer_loop {:?}", f.id, f.outer_loop))?;
        let outer_bound_id = b.alloc("FACE_OUTER_BOUND", vec![s(""), Part21Value::Ref(outer_ref), bool_enum(true)]);
        let mut bounds = vec![Part21Value::Ref(outer_bound_id)];
        for il in &f.inner_loops {
            let &loop_ref = loop_ids.get(il.as_str()).ok_or_else(|| format!("face {:?}: dangling inner_loop {:?}", f.id, il))?;
            let bound_id = b.alloc("FACE_BOUND", vec![s(""), Part21Value::Ref(loop_ref), bool_enum(true)]);
            bounds.push(Part21Value::Ref(bound_id));
        }
        let surface_id = surface_to_part21(&mut b, &f.surface);
        let face_id = b.alloc("ADVANCED_FACE", vec![s(""), Part21Value::List(bounds), Part21Value::Ref(surface_id), bool_enum(f.orientation)]);
        face_ids.insert(f.id.as_str(), face_id);
    }

    let solid_shells: HashSet<&str> = snapshot.solids.iter().flat_map(|so| so.shells.iter().map(|m| m.shell.as_str())).collect();
    let void_shells: HashSet<&str> = snapshot.solids.iter().flat_map(|so| so.shells.iter().filter(|m| m.is_void).map(|m| m.shell.as_str())).collect();
    let mut shell_ids: HashMap<&str, u64> = HashMap::new();
    let mut surface_shells = Vec::new();
    for sh in &snapshot.shells {
        let void = void_shells.contains(sh.id.as_str());
        let mut members = Vec::with_capacity(sh.faces.len());
        for sf in &sh.faces {
            let &face_ref = face_ids.get(sf.face.as_str()).ok_or_else(|| format!("shell {:?}: dangling face {:?}", sh.id, sf.face))?;
            members.push(Part21Value::Ref(if sf.orientation != void { face_ref } else { b.alloc("ORIENTED_FACE", vec![s(""), Part21Value::Derived, Part21Value::Ref(face_ref), bool_enum(false)]) }));
        }
        let closed = solid_shells.contains(sh.id.as_str());
        let shell_id = b.alloc(if closed { "CLOSED_SHELL" } else { "OPEN_SHELL" }, vec![s(""), Part21Value::List(members)]);
        shell_ids.insert(sh.id.as_str(), if void { b.alloc("ORIENTED_CLOSED_SHELL", vec![s(""), Part21Value::Derived, Part21Value::Ref(shell_id), bool_enum(false)]) } else { shell_id });
        if !closed {
            surface_shells.push(Part21Value::Ref(shell_id));
        }
    }
    let shelled_faces: HashSet<&str> = snapshot.shells.iter().flat_map(|sh| sh.faces.iter().map(|sf| sf.face.as_str())).collect();
    for f in snapshot.faces.iter().filter(|f| !shelled_faces.contains(f.id.as_str())) {
        surface_shells.push(Part21Value::Ref(b.alloc("OPEN_SHELL", vec![s(""), Part21Value::List(vec![Part21Value::Ref(face_ids[f.id.as_str()])])])));
    }

    let mut solid_items = Vec::with_capacity(snapshot.solids.len());
    for so in &snapshot.solids {
        let outer = so.shells.iter().find(|m| !m.is_void).ok_or_else(|| format!("solid {:?}: has no non-void outer shell", so.id))?;
        let &outer_ref = shell_ids.get(outer.shell.as_str()).ok_or_else(|| format!("solid {:?}: dangling outer shell {:?}", so.id, outer.shell))?;
        let void_refs: Vec<Part21Value> =
            so.shells.iter().filter(|m| m.is_void).map(|m| shell_ids.get(m.shell.as_str()).copied().map(Part21Value::Ref).ok_or_else(|| format!("solid {:?}: dangling void shell {:?}", so.id, m.shell))).collect::<Result<Vec<_>, _>>()?;
        let solid_id = if void_refs.is_empty() {
            b.alloc("MANIFOLD_SOLID_BREP", vec![s(""), Part21Value::Ref(outer_ref)])
        } else {
            b.alloc("BREP_WITH_VOIDS", vec![s(""), Part21Value::Ref(outer_ref), Part21Value::List(void_refs)])
        };
        solid_items.push(Part21Value::Ref(solid_id));
    }
    representation_to_part21(&mut b, "ADVANCED_BREP_SHAPE_REPRESENTATION", solid_items, context, product_shape);

    let surface_model: Vec<Part21Value> = if surface_shells.is_empty() { Vec::new() } else { vec![Part21Value::Ref(b.alloc("SHELL_BASED_SURFACE_MODEL", vec![s(""), Part21Value::List(surface_shells)]))] };
    representation_to_part21(&mut b, "MANIFOLD_SURFACE_SHAPE_REPRESENTATION", surface_model, context, product_shape);

    let edge_sets: Vec<Part21Value> = free_edge_components(snapshot)
        .into_iter()
        .map(|members| {
            let edges = members.into_iter().map(|i| Part21Value::Ref(edge_ids[snapshot.edges[i].id.as_str()])).collect();
            Part21Value::Ref(b.alloc("CONNECTED_EDGE_SET", vec![s(""), Part21Value::List(edges)]))
        })
        .collect();
    let wireframe: Vec<Part21Value> = if edge_sets.is_empty() { Vec::new() } else { vec![Part21Value::Ref(b.alloc("EDGE_BASED_WIREFRAME_MODEL", vec![s(""), Part21Value::List(edge_sets)]))] };
    representation_to_part21(&mut b, "EDGE_BASED_WIREFRAME_SHAPE_REPRESENTATION", wireframe, context, product_shape);

    let header = Part21Header {
        file_description: vec![Part21Value::List(vec![s("semio brep exchange")]), s("2;1")],
        file_name: vec![s("semio.step"), s(""), Part21Value::List(vec![s("")]), Part21Value::List(vec![s("")]), s("semio"), s("semio"), s("")],
        file_schema: vec![Part21Value::List(vec![s("AUTOMOTIVE_DESIGN")])],
    };
    Ok(b.build(header))
}

/// 📤️ `snapshot` as ISO 10303-21 exchange text — the semio brep's one STEP writer (the kernel's `Brep::export_step`
/// projects the exported shapes to a snapshot and writes it here).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn semio_brep_step_text(snapshot: &SemioBrepSnapshot) -> Result<String, String> {
    semio_brep_part21(snapshot).map(|doc| write_part21(&doc))
}
