//#region 📤️StepExchange
/// 📤️ The kernel-neutral STEP exchange vectors: shapes built by brep kernel verbs, the ISO 10303-21 text the kernel's
/// `export_step` writes for them (byte for byte) and the census a reader recovers — OpenCascade (third party, the
/// `✏️s/🔨️modules/🌐️spatial-kernel/⚙️engine/🧠️semio` suite) reads the same text to the same topology and to the vectors'
/// closed-form measures.
const STEP_EXCHANGE_FIXTURE: &str = include_str!("../../../../../🧫️fixtures/📤️step-exchange/🔣️.json");

fn step_exchange_fixture() -> serde_json::Value {
    let root: serde_json::Value = serde_json::from_str(STEP_EXCHANGE_FIXTURE).expect("step-exchange fixture parses");
    assert_eq!(root["schema"].as_str(), Some("s.stdio.semio.brep.step-exchange/v1"), "fixture schema");
    assert!(!root["cases"].as_array().expect("cases").is_empty() && !root["refusals"].as_array().expect("refusals").is_empty(), "the fixture declares cases and refusals");
    root
}

fn exchange_point(value: &serde_json::Value) -> [f64; 3] {
    let items = value.as_array().expect("fixture point is an array");
    assert_eq!(items.len(), 3, "fixture point has three components");
    [items[0].as_f64().expect("x"), items[1].as_f64().expect("y"), items[2].as_f64().expect("z")]
}

fn exchange_number(value: &serde_json::Value, key: &str) -> f64 {
    value[key].as_f64().unwrap_or_else(|| panic!("fixture field {key} is a number"))
}

fn exchange_shape(kernel: &mut Brep, shape: &serde_json::Value) -> Result<GeometryHandle, BrepError> {
    let points = || shape["points"].as_array().expect("points").iter().map(exchange_point).collect::<Vec<_>>();
    let mut built = match shape["kind"].as_str() {
        Some("box") => kernel.box_prim(exchange_number(shape, "width"), exchange_number(shape, "depth"), exchange_number(shape, "height")),
        Some("cylinder") => kernel.cylinder_prim(exchange_number(shape, "radius"), exchange_number(shape, "height")),
        Some("sphere") => kernel.sphere_prim(exchange_number(shape, "radius")),
        Some("cone") => kernel.cone_prim(exchange_number(shape, "radius"), exchange_number(shape, "height")),
        Some("planarFace") => kernel.planar_face_from_points(&points()),
        Some("polyline") => kernel.polyline_wire(&points()),
        Some("vertex") => kernel.vertex(exchange_point(&shape["point"])),
        Some("planeSurface") => kernel.plane_surface(exchange_point(&shape["origin"]), exchange_point(&shape["normal"])),
        Some("lineCurve") => kernel.line_curve(exchange_point(&shape["start"]), exchange_point(&shape["end"])),
        Some("cut") => {
            let from = exchange_shape(kernel, &shape["from"])?;
            let tool = exchange_shape(kernel, &shape["tool"])?;
            kernel.cut(&from, &tool)
        }
        other => panic!("unknown exchange shape {other:?}"),
    }?;
    for step in shape["steps"].as_array().into_iter().flatten() {
        built = match step["kind"].as_str() {
            Some("translate") => kernel.translate(&built, exchange_point(&step["offset"]))?,
            Some("rotate") => kernel.rotate(&built, exchange_point(&step["axis"]), exchange_number(step, "angle"))?,
            other => panic!("unknown exchange step {other:?}"),
        };
    }
    Ok(built)
}

fn exchange_text(case: &serde_json::Value) -> Result<String, BrepError> {
    let mut kernel = Brep::new();
    let shapes = case["shapes"].as_array().expect("shapes").iter().map(|shape| exchange_shape(&mut kernel, shape)).collect::<Result<Vec<_>, _>>()?;
    kernel.export_step(&shapes)
}

/// 🧾️ What an exchange declares: its shape representations, its length unit and the topology it writes — solid breps, shells,
/// faces and edge curves (stdio's `SemioBrepFromStep` walk and OpenCascade read exactly these entities back).
fn exchange_census(text: &str) -> serde_json::Value {
    let document = semio_s_artifact_stdio_contract::part21::parse_part21(text).expect("the exchange parses as ISO 10303-21");
    let representations: Vec<&str> = document.instances.iter().filter_map(|instance| instance.primary()).map(|(name, _)| name).filter(|name| name.ends_with("_SHAPE_REPRESENTATION")).collect();
    let unit = document.instances.iter().find(|instance| instance.is_type("LENGTH_UNIT")).and_then(|instance| instance.entity("SI_UNIT")).expect("an SI length unit");
    let length_unit = match (unit[0].as_enum(), unit[1].as_enum().expect("SI unit name")) {
        (Some(prefix), name) => format!("{prefix}.{name}"),
        (None, name) => name.to_string(),
    };
    let count = |names: &[&str]| document.instances.iter().filter(|instance| names.iter().any(|name| instance.is_type(name))).count();
    serde_json::json!({ "representations": representations, "lengthUnit": length_unit, "solids": count(&["MANIFOLD_SOLID_BREP", "BREP_WITH_VOIDS"]), "shells": count(&["CLOSED_SHELL", "OPEN_SHELL"]), "faces": count(&["ADVANCED_FACE"]), "edges": count(&["EDGE_CURVE"]) })
}

/// ⚖️ Every vector's shapes export to the fixture's exact exchange text, and that text reads back to the fixture's census —
/// the text OpenCascade is held to is the text the kernel writes today.
#[semio_framework_async_macros::async_test]
async fn every_step_exchange_vector_is_written_byte_for_byte() {
    for case in step_exchange_fixture()["cases"].as_array().expect("cases") {
        let id = case["id"].as_str().expect("id");
        let text = exchange_text(case).unwrap_or_else(|error| panic!("{id}: export refused: {error}"));
        assert_eq!(text, case["step"].as_str().expect("step"), "{id}: exchange text drifted (regenerate with `-- --ignored print_step_exchange_fixture`)");
        let census = exchange_census(&text);
        for key in ["representations", "lengthUnit", "solids", "shells", "faces", "edges"] {
            assert_eq!(census[key], case["expect"][key], "{id}: {key}");
        }
    }
}

/// ⚖️ Every refusal is refused as invalid input: nothing to exchange, or a vertex/curve/surface that has no shape
/// representation.
#[semio_framework_async_macros::async_test]
async fn every_step_exchange_refusal_is_refused() {
    for refusal in step_exchange_fixture()["refusals"].as_array().expect("refusals") {
        let id = refusal["id"].as_str().expect("id");
        assert!(matches!(exchange_text(refusal), Err(BrepError::InvalidInput(_))), "{id}: must be refused as invalid input");
    }
}

/// 🖨️ Prints the fixture with every case's `step` and census regenerated from the kernel — run after a deliberate writer
/// change (`cargo test … -- --ignored print_step_exchange_fixture --nocapture`), review, commit. A case the kernel refuses is
/// named on stderr and left out of the printed fixture.
#[test]
#[ignore]
fn print_step_exchange_fixture() {
    let mut root = step_exchange_fixture();
    let cases: Vec<serde_json::Value> = root["cases"].as_array().expect("cases").iter().filter_map(|case| match exchange_text(case) {
        Ok(text) => {
            let census = exchange_census(&text);
            let mut case = case.clone();
            for key in ["representations", "lengthUnit", "solids", "shells", "faces", "edges"] {
                case["expect"][key] = census[key].clone();
            }
            case["step"] = serde_json::Value::String(text);
            Some(case)
        }
        Err(error) => {
            eprintln!("REFUSED {}: {error}", case["id"]);
            None
        }
    }).collect();
    root["cases"] = serde_json::Value::Array(cases);
    println!("{}", serde_json::to_string_pretty(&root).expect("fixture json"));
}
