        for shape in shapes {
            let entity = self.entity(shape)?;
            if matches!(entity, Entity::Vertex(_) | Entity::Curve(..) | Entity::Surface(..)) {
                return Err(BrepError::InvalidInput(format!("{} is a {:?}: a STEP exchange carries solids, shells, faces, wires and edges", shape.as_str(), self.kind_sync(shape)?)));
