            roots.extend(entity_roots(entity));
        }
        let mut body = self.body.clone();
        let keep = body.reachable_from(&roots);
        body.compact(&keep);
        semio_brep_step_text(&body.to_snapshot()).map_err(BrepError::Operation)
    }
