const STEP_EXCHANGE_FIXTURE_PATH = "../../../../🔌️plugins/🗄️stdio/🗿️artifacts/🧿️semio/🏅️standards/🔖️v1/🪆️subsets/🧊️brep/🧫️fixtures/📤️step-exchange/🔣️.json";

/** 📤️ `s.stdio.semio.brep.step-exchange/v1` — the exact ISO 10303-21 text the Rust kernel's `export_step` writes for shapes built
 * by kernel verbs, the census a reader recovers and the closed-form measures of the exchanged geometry.
 * @see ../../../../../../🔌️plugins/🗄️stdio/🗿️artifacts/🧿️semio/🏅️standards/🔖️v1/🪆️subsets/🧊️brep/🧫️fixtures/📤️step-exchange/🔣️.json */
type ExchangeStep = { readonly kind: "translate"; readonly offset: Vec3 } | { readonly kind: "rotate"; readonly axis: Vec3; readonly angle: number };
type ExchangeShape =
  | { readonly kind: "box"; readonly width: number; readonly depth: number; readonly height: number; readonly steps?: readonly ExchangeStep[] }
  | { readonly kind: "sphere"; readonly radius: number; readonly steps?: readonly ExchangeStep[] }
  | { readonly kind: "cylinder" | "cone"; readonly radius: number; readonly height: number; readonly steps?: readonly ExchangeStep[] }
  | { readonly kind: "planarFace" | "polyline"; readonly points: readonly Vec3[]; readonly steps?: readonly ExchangeStep[] }
  | { readonly kind: "cut"; readonly from: ExchangeShape; readonly tool: ExchangeShape; readonly steps?: readonly ExchangeStep[] }
  | { readonly kind: "vertex"; readonly point: Vec3; readonly steps?: readonly ExchangeStep[] }
  | { readonly kind: "planeSurface"; readonly origin: Vec3; readonly normal: Vec3; readonly steps?: readonly ExchangeStep[] }
  | { readonly kind: "lineCurve"; readonly start: Vec3; readonly end: Vec3; readonly steps?: readonly ExchangeStep[] };
type ExchangeExpect = {
  readonly representations: readonly string[];
  readonly lengthUnit: "METRE";
  readonly solids: number;
  readonly shells: number;
  readonly faces: number;
  readonly edges: number;
  readonly volume?: number;
  readonly area?: number;
  readonly length?: number;
  readonly bounds: { readonly min: Vec3; readonly max: Vec3 };
};
type ExchangeCase = { readonly id: string; readonly shapes: readonly ExchangeShape[]; readonly expect: ExchangeExpect; readonly step: string };
type ExchangeRefusal = { readonly id: string; readonly shapes: readonly ExchangeShape[] };
type ExchangeFixture = { readonly schema: "s.stdio.semio.brep.step-exchange/v1"; readonly oracleRelativeTolerance: number; readonly boundsTolerance: number; readonly cases: readonly ExchangeCase[]; readonly refusals: readonly ExchangeRefusal[] };

/** 📐️ OpenCascade's session length unit is the millimetre; it converts the exchange's declared metre on import. */
const OPEN_CASCADE_MILLIMETRES_PER_METRE = 1000;

/** 📥️ Reads the fixture and refuses a renamed contract or an empty case list, so a drift never passes over zero vectors. */
async function stepExchangeFixture(source: TestSource): Promise<ExchangeFixture> {
  const { readFile } = await import("node:fs/promises");
  const root = JSON.parse(await readFile(new URL(STEP_EXCHANGE_FIXTURE_PATH, source.url), "utf8")) as ExchangeFixture;
  if (root.schema !== "s.stdio.semio.brep.step-exchange/v1" || root.cases.length === 0 || root.refusals.length === 0) throw new Error(`step-exchange fixture contract drifted: ${root.schema}`);
  return root;
}

/** 🔮️ OpenCascade reads every vector's exchange text (`textOf`): every disagreement with the fixture's census and measures, as
 * readable lines. */
async function openCascadeExchangeDisagreements(fixture: ExchangeFixture, textOf: (row: ExchangeCase) => Promise<string>): Promise<string[]> {
  const occt = await import("../../../../../../🔌️plugins/📐️cad/⚙️engine/🧱️brepjs/🟦️.ts");
  const wasmFile = await occt.resolveOwnedOpenCascadeWasmFileUrl();
  await occt.initializeOwnedOpenCascade((path) => (path === "brepjs_single.wasm" ? wasmFile : path));
  const out: string[] = [];
  for (const row of fixture.cases) {
    const shape = occt.unwrap(await occt.importSTEP(new Blob([await textOf(row)])));
    const near = (label: string, got: number, want: number, tolerance: number) => {
      if (!(Math.abs(got - want) <= tolerance)) out.push(`${row.id}: ${label} ${got} != ${want} (±${tolerance})`);
    };
    const count = (label: string, got: number, want: number) => {
      if (got !== want) out.push(`${row.id}: ${label} ${got} != ${want}`);
    };
    count("solids", occt.getSolids(shape).length, row.expect.solids);
    count("shells", occt.getShells(shape).length, row.expect.shells);
    count("faces", occt.getFaces(shape).length, row.expect.faces);
    count("edges", occt.getEdges(shape).length, row.expect.edges);
    const metres = (value: number, dimension: number) => value / OPEN_CASCADE_MILLIMETRES_PER_METRE ** dimension;
    if (row.expect.volume !== undefined) near("volume", metres(occt.unwrap(occt.measureVolume(shape)), 3), row.expect.volume, fixture.oracleRelativeTolerance * row.expect.volume);
    if (row.expect.area !== undefined) near("area", metres(occt.unwrap(occt.measureArea(shape)), 2), row.expect.area, fixture.oracleRelativeTolerance * row.expect.area);
    if (row.expect.length !== undefined) near("length", metres(occt.unwrap(occt.measureLength(shape)), 1), row.expect.length, fixture.oracleRelativeTolerance * row.expect.length);
    const bounds = occt.getBounds(shape);
    [bounds.xMin, bounds.yMin, bounds.zMin].forEach((got, axis) => near(`bounds.min[${axis}]`, metres(got, 1), row.expect.bounds.min[axis]!, fixture.boundsTolerance));
    [bounds.xMax, bounds.yMax, bounds.zMax].forEach((got, axis) => near(`bounds.max[${axis}]`, metres(got, 1), row.expect.bounds.max[axis]!, fixture.boundsTolerance));
  }
  return out;
}

/** 🧠️ The CAD runtime's own path over the `brep_invoke` wire (flow-core wasm): `exportText` builds a vector's shapes with the
 * kernel verbs, in fixture order, and exports them; `refusalDisagreements` lists every refusal the wire accepted (a refusal
 * whose shape kind no verb declares is not expressible on the wire). */
async function semioExchangeOps(): Promise<{ readonly exportText: (shapes: readonly ExchangeShape[]) => Promise<string>; readonly refusalDisagreements: (fixture: ExchangeFixture) => Promise<string[]> }> {
  const { invokeBrep } = await import("@semio-tech/s-3d-js");
  const handle = async (method: string, args: Record<string, unknown>) => (await invokeBrep<{ readonly handle: string }>(method, args)).handle;
  const primitive = async (shape: ExchangeShape): Promise<string> => {
    switch (shape.kind) {
      case "box":
        return handle("box", { width: shape.width, depth: shape.depth, height: shape.height });
      case "sphere":
        return handle("sphere", { radius: shape.radius });
      case "cylinder":
      case "cone":
        return handle(shape.kind, { radius: shape.radius, height: shape.height });
      case "planarFace":
        return handle("planarFaceFromPoints", { points: shape.points });
      case "polyline":
        return handle("polylineWire", { points: shape.points });
      case "lineCurve":
        return handle("lineCurve", { start: shape.start, end: shape.end });
      case "cut":
        return handle("cut", { a: await build(shape.from), b: await build(shape.tool) });
      default:
        throw new Error(`${shape.kind}: no brep_invoke verb`);
    }
  };
  const build = async (shape: ExchangeShape): Promise<string> => {
    let built = await primitive(shape);
    for (const step of shape.steps ?? []) built = step.kind === "translate" ? await handle("translate", { shape: built, offset: step.offset }) : await handle("rotate", { shape: built, axis: step.axis, angle: step.angle });
    return built;
  };
  const exportText = async (shapes: readonly ExchangeShape[]) => {
    const handles: string[] = [];
    for (const shape of shapes) handles.push(await build(shape));
    return (await invokeBrep<{ readonly value: string }>("exportStep", { shapes: handles })).value;
  };
  const refusalDisagreements = async (fixture: ExchangeFixture) => {
    const out: string[] = [];
    for (const refusal of fixture.refusals.filter((row) => row.shapes.every((shape) => shape.kind !== "vertex" && shape.kind !== "planeSurface"))) {
      if (await exportText(refusal.shapes).then(() => true, () => false)) out.push(`${refusal.id}: exported a shape without a representation`);
    }
    return out;
  };
  return { exportText, refusalDisagreements };
}

